<?php
declare(strict_types=1);
require_once '../config/config.php'; require_once '../includes/church-book-functions.php';
if(!isset($conn)||!($conn instanceof mysqli))die('Database connection not found.');$conn->set_charset('utf8mb4');
$token=cb_clean($_GET['token']??$_POST['token']??'');$invite=cb_registration_link_lookup($conn,'wedding_registration_links',$token,false);$csrf=cb_csrf_token();$errors=[];$success=false;$existing=null;
if($invite&&!empty($invite['wedding_id']))$existing=cb_fetch_one($conn,"SELECT * FROM wedding_vows WHERE id=?",'i',[(int)$invite['wedding_id']]);
$site=cb_site_setting($conn,'site_name','Church');$logo=cb_site_setting($conn,'site_logo',cb_site_setting($conn,'logo',''));if($logo!==''&&!preg_match('~^https?://~i',$logo))$logo=cb_absolute_base_url().ltrim($logo,'/');
function pv(string $k,mixed $fallback=''): string { global $existing,$invite; return cb_h($_POST[$k]??($existing[$k]??($k==='groom_name'?($invite['recipient_name']??$fallback):($k==='groom_phone'?($invite['recipient_phone']??$fallback):$fallback)))); }
if($_SERVER['REQUEST_METHOD']==='POST'&&$invite){cb_verify_csrf();$f=[];foreach(['wedding_date','wedding_time','venue','groom_name','groom_phone','groom_address','groom_father','groom_mother','bride_name','bride_phone','bride_address','bride_father','bride_mother','ceremony_type','witness_1','witness_2','scripture_theme','vows_text','remarks'] as $k)$f[$k]=cb_clean($_POST[$k]??'');
 if($f['wedding_date']===''||!cb_valid_date($f['wedding_date'])||$f['groom_name']===''||$f['bride_name']==='')$errors[]='Wedding date, groom name and bride name are required.'; if(!in_array($f['ceremony_type'],['Banns','Licence','Special Licence','Other'],true))$f['ceremony_type']='Banns';
 if(!$errors){$conn->begin_transaction();try{$locked=cb_registration_link_lookup($conn,'wedding_registration_links',$token,true);if(!$locked)throw new RuntimeException('This registration link is no longer available.');$linkId=(int)$locked['id'];$weddingId=cb_nullable_int($locked['wedding_id']??null);$time=$f['wedding_time']!==''?$f['wedding_time']:null;$notePrefix='Self-registered/updated by groom using public wedding registration link.';$remarks=trim($notePrefix.($f['remarks']!==''?' '.$f['remarks']:''));
 if($weddingId){$stmt=$conn->prepare("UPDATE wedding_vows SET wedding_date=?,wedding_time=?,venue=?,groom_name=?,groom_phone=?,groom_address=?,groom_father=?,groom_mother=?,bride_name=?,bride_phone=?,bride_address=?,bride_father=?,bride_mother=?,ceremony_type=?,witness_1=?,witness_2=?,scripture_theme=?,vows_text=?,remarks=?,self_registered=1,registration_link_id=? WHERE id=?");$stmt->bind_param('sssssssssssssssssssii',$f['wedding_date'],$time,$f['venue'],$f['groom_name'],$f['groom_phone'],$f['groom_address'],$f['groom_father'],$f['groom_mother'],$f['bride_name'],$f['bride_phone'],$f['bride_address'],$f['bride_father'],$f['bride_mother'],$f['ceremony_type'],$f['witness_1'],$f['witness_2'],$f['scripture_theme'],$f['vows_text'],$remarks,$linkId,$weddingId);if(!$stmt->execute())throw new RuntimeException('Unable to update wedding registration: '.$stmt->error);$stmt->close();}
 else{$status='Scheduled';$stmt=$conn->prepare("INSERT INTO wedding_vows(wedding_date,wedding_time,venue,status,groom_name,groom_phone,groom_address,groom_father,groom_mother,bride_name,bride_phone,bride_address,bride_father,bride_mother,ceremony_type,witness_1,witness_2,scripture_theme,vows_text,remarks,self_registered,registration_link_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,1,?)");$stmt->bind_param('ssssssssssssssssssssi',$f['wedding_date'],$time,$f['venue'],$status,$f['groom_name'],$f['groom_phone'],$f['groom_address'],$f['groom_father'],$f['groom_mother'],$f['bride_name'],$f['bride_phone'],$f['bride_address'],$f['bride_father'],$f['bride_mother'],$f['ceremony_type'],$f['witness_1'],$f['witness_2'],$f['scripture_theme'],$f['vows_text'],$remarks,$linkId);if(!$stmt->execute())throw new RuntimeException('Unable to save wedding registration: '.$stmt->error);$weddingId=(int)$conn->insert_id;$stmt->close();$register='WV-'.date('Y',strtotime($f['wedding_date'])).'-'.str_pad((string)$weddingId,5,'0',STR_PAD_LEFT);$u=$conn->prepare("UPDATE wedding_vows SET register_no=? WHERE id=? AND (register_no IS NULL OR register_no='')");$u->bind_param('si',$register,$weddingId);$u->execute();$u->close();}
 cb_consume_registration_link($conn,'wedding_registration_links',$locked);$conn->commit();$success=true;}catch(Throwable $e){$conn->rollback();$errors[]=$e->getMessage();}}
}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Groom Registration - <?= cb_h($site) ?></title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css"><link rel="stylesheet" href="../assets/css/public-registration.css"><link rel="stylesheet" href="../assets/css/form-tabs.css"><?= site_theme_css() ?></head><body><div class="pr-wrap"><div class="pr-card"><div class="pr-head"><?php if($logo):?><img class="pr-logo" src="<?= cb_h($logo) ?>" alt="<?= cb_h($site) ?> Logo"><?php endif;?><h1>Wedding / Groom Registration</h1><p><?= cb_h($site) ?></p></div><div class="pr-body">
