<?php else:?><?php foreach($errors as $e):?><div class="pr-alert pr-error"><?= cb_h($e) ?></div><?php endforeach;?><p class="pr-note">The groom should complete the couple's details below. The church office can review and complete banns, certificate and officiant information later.</p><form method="post" data-form-tabs><input type="hidden" name="csrf_token" value="<?= cb_h($csrf) ?>"><input type="hidden" name="token" value="<?= cb_h($token) ?>"><div class="pr-grid">
<div class="pr-section">Wedding Details</div><div class="pr-field"><label>Wedding Date *</label><input class="pr-input" type="date" name="wedding_date" required value="<?= pv('wedding_date') ?>"></div><div class="pr-field"><label>Wedding Time</label><input class="pr-input" type="time" name="wedding_time" value="<?= pv('wedding_time') ?>"></div><div class="pr-field span-2"><label>Venue</label><input class="pr-input" name="venue" maxlength="180" value="<?= pv('venue') ?>"></div>
<div class="pr-section">Groom</div><div class="pr-field"><label>Groom Full Name *</label><input class="pr-input" name="groom_name" maxlength="180" required value="<?= pv('groom_name') ?>"></div><div class="pr-field"><label>Phone</label><input class="pr-input" name="groom_phone" maxlength="50" value="<?= pv('groom_phone') ?>"></div><div class="pr-field span-2"><label>Address / Residence</label><input class="pr-input" name="groom_address" maxlength="255" value="<?= pv('groom_address') ?>"></div><div class="pr-field"><label>Father's Name</label><input class="pr-input" name="groom_father" maxlength="180" value="<?= pv('groom_father') ?>"></div><div class="pr-field"><label>Mother's Name</label><input class="pr-input" name="groom_mother" maxlength="180" value="<?= pv('groom_mother') ?>"></div>
<div class="pr-section">Bride</div><div class="pr-field"><label>Bride Full Name *</label><input class="pr-input" name="bride_name" maxlength="180" required value="<?= pv('bride_name') ?>"></div><div class="pr-field"><label>Phone</label><input class="pr-input" name="bride_phone" maxlength="50" value="<?= pv('bride_phone') ?>"></div><div class="pr-field span-2"><label>Address / Residence</label><input class="pr-input" name="bride_address" maxlength="255" value="<?= pv('bride_address') ?>"></div><div class="pr-field"><label>Father's Name</label><input class="pr-input" name="bride_father" maxlength="180" value="<?= pv('bride_father') ?>"></div><div class="pr-field"><label>Mother's Name</label><input class="pr-input" name="bride_mother" maxlength="180" value="<?= pv('bride_mother') ?>"></div>
<div class="pr-section">Ceremony & Witnesses</div><div class="pr-field"><label>Ceremony Basis</label><select class="pr-select" name="ceremony_type"><?php foreach(['Banns','Licence','Special Licence','Other'] as $s):?><option <?= (($_POST['ceremony_type']??($existing['ceremony_type']??'Banns'))===$s)?'selected':'' ?>><?= cb_h($s) ?></option><?php endforeach;?></select></div><div class="pr-field"><label>Witness 1</label><input class="pr-input" name="witness_1" maxlength="180" value="<?= pv('witness_1') ?>"></div><div class="pr-field"><label>Witness 2</label><input class="pr-input" name="witness_2" maxlength="180" value="<?= pv('witness_2') ?>"></div><div class="pr-field"><label>Scripture / Theme</label><input class="pr-input" name="scripture_theme" maxlength="255" value="<?= pv('scripture_theme') ?>"></div><div class="pr-field span-2"><label>Wedding Vows / Declaration (optional)</label><textarea class="pr-textarea" name="vows_text"><?= pv('vows_text') ?></textarea></div><div class="pr-field span-2"><label>Additional Information</label><textarea class="pr-textarea" name="remarks"><?= pv('remarks') ?></textarea></div></div><div class="pr-actions"><button class="pr-btn" type="submit"><i class="fas fa-paper-plane"></i> Submit Wedding Details</button></div></form><?php endif;?></div></div></div><script src="../assets/js/form-tabs.js"></script></body></html>
